INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63619428', 63619428, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Junior Penyusunan Analisis Hukum Kerjasama Pemerintah dengan Badan Usaha', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 80000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan penelaahan mendalam terhadap dokumen draf awal Standar Operasional Prosedur Panel Badan Penyiapan dan kajian dokumen Kerjasama Pemerintah dan Badan Usaha (KPBU) sederhana melalui pemberian rekomendasi teknis dan substansif; 2. Melakukan penelaahan terhadap draf awal Standar Operasional Prosedur Panel Badan Penyiapan serta memberikan rekomendasi teknis dan substantif; 3. Memberikan masukan dalam penyusunan rekomendasi teknis dan substantif terhadap dokumen KPBU sederhana; 4. Menyusun materi diseminasi dan narasi strategis dalam rangka fasilitasi forum sosialisasi internal SOP Panel Badan Penyiapan dan Peraturan Eselon 1 tentang KPBU Sederhana; 5. Menyusun materi diseminasi dan narasi strategis untuk memfasilitasi forum sosialisasi internal terkait Standar Operasional Prosedur Panel Badan Penyiapan; 6. Menyusun materi diseminasi dan narasi strategis untuk memfasilitasi forum sosialisasi internal terkait Peraturan Eselon 1 tentang KPBU Sederhana; 7. Melakukan legalisasi dan formalisasi dokumen berupa Surat Keputusan SOP Panel Badan Penyiapan dan pengundangan Peraturan Eselon 1 tentang KPBU Sederhana. 8. Melakukan koordinasi proses pengesahan dokumen Surat Keputusan (SK) terkait Standar Operasional Prosedur Panel Badan Penyiapan. 9. Melakukan koordinasi proses pengundangan Peraturan Eselon 1 tentang KPBU Sederhana. 10. Melakukan koordinasi dengan pihak terkait mengenai pelaksanaan Kantor Bersama.', '1. Pendidikan minimal Sarjana (S1) jurusan Ilmu Hukum yang dibuktikan dengan ijasah; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik dilingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, yang dibuktikan dengan kontrak/surat keterangan kerja; 3. Pekerjaan sejenis di bidang menyiapkan draft peraturan, yang dibuktikan dengan kontrak kerja/surat keterangan kerja; 4. Tidak sedang dalam kontrak dengan unit kerja lain di Kementerian PPN/Bappenas; 5. Diutamakan Konsultan Individu dalam negeri (dibuktikan dengan identitas kewarganegaan Indonesia seperti Kartu Tanda Penduduk; 6. Memiliki Nomor Pokok Wajib Pajak (NPWP); dan 7. Dapat menerima sistem pembayaran gaji sesuai dengan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1050787);
