INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63642187', 63642187, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Kabel telepon 4x0,5mm', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 40000, 'January 2026', 'APBD', 1, 1, '8 Meter', 'Kegiatan ini meliputi perencanaan kebutuhan, pengadaan, dan penggantian komponen instalasi listrik guna memastikan seluruh sistem penerangan dan kelistrikan gedung berfungsi secara aman dan berkelanjutan. Selain itu, tugas ini mencakup pemeriksaan berkala terhadap panel listrik serta pengelolaan stok suku cadang untuk mendukung kelancaran operasional dan kenyamanan lingkungan kerja di kantor.', 'Komponen instalasi listrik yang disediakan wajib memiliki sertifikasi standar keamanan SNI (Standar Nasional Indonesia) serta label LMK (Lembaga Masalah Kelistrikan) guna menjamin proteksi maksimal terhadap risiko gagal fungsi dan kebakaran. Spesifikasi teknis difokuskan pada penggunaan lampu hemat energi (LED) dengan efikasi tinggi untuk efisiensi daya, serta material pendukung seperti kabel dan sakelar yang memiliki ketahanan beban tinggi sesuai dengan kapasitas daya serta kebutuhan operasional bangunan gedung.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1054145);
