INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63642191', 63642191, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Makan Rapat Rutin', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 5400000, 'January 2026', 'APBD', 1, 1, '180 Orang / AcaraKali', 'Kegiatan ini mencakup manajemen rantai pasok internal mulai dari perencanaan volume kebutuhan hingga pendistribusian bahan logistik kantor untuk mendukung kelancaran administrasi di setiap unit kerja. Lingkup tugasnya meliputi inventarisasi stok secara berkala, pengadaan barang konsumabel kantor, serta penatausahaan dokumen pergudangan guna memastikan ketersediaan logistik yang tepat jumlah dan tepat waktu bagi seluruh pegawai.', 'Bahan logistik kantor yang disediakan harus memenuhi standar kualitas terbaik dan kompatibel dengan perangkat kerja yang ada guna mencegah kerusakan alat dan menjamin hasil kerja yang optimal. Spesifikasi teknis mengutamakan aspek fungsionalitas barang, penggunaan material yang ramah lingkungan, serta jaminan ketersediaan produk di pasar untuk menjaga konsistensi dan keseragaman standar perlengkapan kantor yang digunakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1054792);
