INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63644663', 63644663, 'analyze_legacy', 'Kementerian Perindustrian', 'central', 'Direktorat Jenderal Industri Logam Mesin Alat Transportasi Dan Elektronika', 'Pemeliharaan Kendaraan Roda 2 Konvensional', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 49104000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 11, Unit, @ 4464000 )', '1. Pemeliharaan Kendaraan Roda 2 Konvensional ( 11, Unit, @ 4464000 );', 'Pekerjaan pemeliharaan kendaraan dinas operasional roda 2 konvensional di lingkungan Direktorat Jenderal ILMATE meliputi seluruh kegiatan perawatan dan perbaikan sepeda motor berbahan bakar konvensional (bensin) yang digunakan sebagai kendaraan dinas operasional. Pemeliharaan bertujuan untuk menjaga kondisi kendaraan agar tetap laik jalan, aman, dan siap digunakan dalam mendukung kelancaran pelaksanaan tugas kedinasan. Objek pemeliharaan adalah kendaraan dinas operasional roda 2 konvensional yang digunakan untuk kegiatan operasional kantor, pelayanan lapangan, serta kegiatan pendukung lainnya. Kegiatan pemeliharaan kendaraan roda 2 konvensional meliputi : - Servis berkala sesuai standar dan rekomendasi pabrikan - Penggantian oli mesin dan cairan pendukung lainnya - Pemeriksaan dan pembersihan sistem bahan bakar - Pemeriksaan dan penyetelan sistem pengapian - Pemeriksaan dan perawatan sistem rem (depan dan belakang) - Pemeriksaan sistem kelistrikan dan kondisi aki - Pemeriksaan dan penyetelan rantai atau sistem penggerak - Pemeriksaan kondisi ban dan tekanan udara - Pemeriksaan suspensi dan kemudi - Penggantian suku cadang habis pakai sesuai kebutuhan - Pencucian dan perawatan kebersihan kendaraan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1056002);
