INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63644660', 63644660, 'analyze_legacy', 'Kementerian Perindustrian', 'central', 'Direktorat Jenderal Industri Logam Mesin Alat Transportasi Dan Elektronika', 'Pemeliharaan Kendaraan Roda 4 Eselon I Berbasis Baterai Sewa', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 9990000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '( 1, Unit, @ 9990000 )', '1. Pemeliharaan Kendaraan Roda 4 Eselon I Berbasis Baterai Sewa ( 1, Unit, @ 9990000 );', 'Dalam rangka mendukung mobilitas Pejabat Eselon I serta kebijakan penggunaan kendaraan ramah lingkungan, Direktorat Jenderal ILMATE menggunakan kendaraan dinas roda 4 berbasis baterai (kendaraan listrik) dengan skema sewa. Agar kendaraan tersebut selalu dalam kondisi prima, aman, dan siap digunakan, diperlukan pekerjaan pemeliharaan yang terencana dan berkelanjutan sesuai karakteristik kendaraan listrik. Maksud dari pekerjaan pemeliharaan kendaraan roda 4 Eselon I berbasis baterai (sewa) adalah menjaga performa, keandalan, dan keselamatan kendaraan selama masa sewa. Tujuan pekerjaan ini adalah memastikan kendaraan selalu laik jalan, mendukung kelancaran tugas kedinasan Pejabat Eselon I, serta memperpanjang umur pakai komponen kendaraan sesuai ketentuan pabrikan dan perjanjian sewa. Kegiatan pemeliharaan kendaraan roda 4 berbasis baterai meliputi : - Pemeriksaan kondisi baterai, sistem pengisian daya (charging system), dan indikator kesehatan baterai - Pemeriksaan dan perawatan sistem kelistrikan kendaraan - Pemeriksaan sistem penggerak (motor listrik dan komponen pendukung) - Pemeriksaan sistem rem, suspensi, dan kemudi - Pemeriksaan sistem pendingin baterai dan komponen elektronik - Pemeriksaan dan penggantian komponen habis pakai sesuai rekomendasi pabrikan - Pemeriksaan perangkat lunak kendaraan (software/firmware) apabila diperlukan - Pencucian dan perawatan kebersihan interior dan eksterior kendaraan - Penanganan gangguan ringan selama masa operasional.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1056006);
