INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63644665', 63644665, 'analyze_legacy', 'Kementerian Perindustrian', 'central', 'Direktorat Jenderal Industri Logam Mesin Alat Transportasi Dan Elektronika', 'Biaya perpanjangan STNK', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 43200000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 32, Unit, @ 1350000 )', '1. Biaya perpanjangan STNK ( 32, Unit, @ 1350000 );', 'Dalam rangka menjamin legalitas dan kelayakan operasional kendaraan dinas di lingkungan Direktorat Jenderal ILMATE, diperlukan pemenuhan kewajiban administrasi kendaraan bermotor berupa perpanjangan Surat Tanda Nomor Kendaraan (STNK) secara berkala. Perpanjangan STNK merupakan kewajiban yang harus dipenuhi agar kendaraan dinas dapat digunakan secara sah sesuai dengan ketentuan peraturan perundang-undangan yang berlaku. Uraian kegiatan biaya perpanjangan STNK meliputi : - Pendataan kendaraan dinas yang akan dilakukan perpanjangan STNK; - Persiapan dan kelengkapan dokumen kendaraan; - Pembayaran kewajiban perpanjangan STNK sesuai ketentuan yang berlaku (pajak kendaraan bermotor dan biaya administrasi); - Pengurusan proses perpanjangan STNK melalui instansi terkait - Pengambilan dan pendistribusian STNK yang telah diperpanjang - Pendokumentasian dan pengarsipan dokumen perpanjangan STNK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1056231);
